+          <span class="item" role="treeitem" aria-disabled="true">Unavailable</span>
+          <a class="item" role="treeitem" href="#rubric">Rubric</a>
+        </div>
+      </div>
+    </div>`;
+  const tree = document.querySelector<HTMLElement>('[role="tree"]')!;
