/**
 * @component tree-browser
 * @selector .pfx-tree-browser
 * @summary A tree of nested collections and leaf items, with rotating chevrons.
 * @remarks Load the tree-browser interaction bundle for ARIA-tree keyboard navigation and expansion. Native `<details>` markup remains a CSS-only disclosure fallback; don't give that fallback ARIA-tree roles.
 * @modifier -icon-* — Render folder/file glyph icons in summaries and leaf items.
 * @modifier -size-sm — Small.
 * @modifier -size-lg — Large.
 * @part .item — A leaf entry in the tree.
 * @pseudo ::before — Draws each collection's disclosure chevron, a masked glyph that rotates to point down when the branch is open.
 * @cssstate open
 * @a11y Name the `role="tree"` root, use focusable `role="treeitem"` nodes, and associate each collection with its `role="group"` via `aria-owns`. Load `@pantoken/interactions/tree-browser.js` for one tab stop and synchronized expansion. Add `aria-selected` to opt into single selection; focus alone doesn't select.
 * @example -canvas-rce -docs
 * ```html
 * <div class="pfx-tree-browser" role="tree" aria-label="Course files">
 *   <div role="none">
 *     <div role="treeitem" tabindex="0" aria-expanded="true" aria-labelledby="course-tree-label" aria-owns="course-tree-group">
 *       <span class="item" id="course-tree-label"><span class="pfx-icon -icon-folder" aria-hidden="true"></span> Course files</span>
 *     </div>
 *     <div role="group" id="course-tree-group">
 *       <a class="item" role="treeitem" tabindex="-1" href="#syllabus">Syllabus.pdf</a>
 *       <div role="none">
 *         <div role="treeitem" tabindex="-1" aria-expanded="false" aria-labelledby="week-tree-label" aria-owns="week-tree-group">
 *           <span class="item" id="week-tree-label"><span class="pfx-icon -icon-folder" aria-hidden="true"></span> Week 1</span>
 *         </div>
 *         <div role="group" id="week-tree-group" hidden>
 *           <a class="item" role="treeitem" tabindex="-1" href="#reading">Reading.pdf</a>
 *           <a class="item" role="treeitem" tabindex="-1" href="#slides">Slides.pptx</a>
 *         </div>
 *       </div>
 *       <a class="item" role="treeitem" tabindex="-1" href="#rubric">Rubric.docx</a>
 *     </div>
 *   </div>
 * </div>
 * ```
 * @structure
 * .pfx-tree-browser {
 *   [role="none"] {
 *     [role="treeitem"] {
 *       .item {}
 *     }
 *     [role="group"]:optional {}
 *   }
 * }
 * @related menu — Both present nested, selectable entries.
 * @example -automatica11y
 * ```html
 * <div class="pfx-tree-browser" role="tree" aria-label="Course files">
 *   <div role="none">
 *     <div role="treeitem" tabindex="0" aria-expanded="true" aria-labelledby="course-tree-label" aria-owns="course-tree-group">
 *       <span class="item" id="course-tree-label"><span class="pfx-icon -icon-folder" aria-hidden="true"></span> Course files</span>
 *     </div>
 *     <div role="group" id="course-tree-group">
 *       <a class="item" role="treeitem" tabindex="-1" href="#syllabus">Syllabus.pdf</a>
 *       <div role="none">
 *         <div role="treeitem" tabindex="-1" aria-expanded="false" aria-labelledby="week-tree-label" aria-owns="week-tree-group">
 *           <span class="item" id="week-tree-label"><span class="pfx-icon -icon-folder" aria-hidden="true"></span> Week 1</span>
 *         </div>
 *         <div role="group" id="week-tree-group" hidden>
 *           <a class="item" role="treeitem" tabindex="-1" href="#reading">Reading.pdf</a>
 *           <a class="item" role="treeitem" tabindex="-1" href="#slides">Slides.pptx</a>
 *         </div>
 *       </div>
 *       <a class="item" role="treeitem" tabindex="-1" href="#rubric">Rubric.docx</a>
 *     </div>
 *   </div>
 * </div>
 * ```
 */
@scope (.pfx-tree-browser) {
  & {
    border-radius: var(--instui-component-tree-browser-border-radius);
    font-family: var(--instui-component-tree-browser-tree-collection-font-family);
    color: var(--instui-component-tree-browser-tree-button-name-text-color);
  }

  /* A collection node (a <details><summary>) and a leaf (.item) share the button chrome. */
  & details > summary,
  & .item {
    display: flex;
    align-items: center;
    gap: var(--instui-component-tree-browser-tree-button-icons-margin-right-medium);
    padding: var(--instui-component-tree-browser-tree-button-base-spacing-medium);
    font-size: var(--instui-component-tree-browser-tree-button-name-font-size-medium);
    line-height: var(--instui-component-tree-browser-tree-button-text-line-height);
    color: var(--instui-component-tree-browser-tree-button-name-text-color);
    border-radius: var(--instui-component-tree-browser-tree-button-border-radius);
    cursor: pointer;
    list-style: none;
  }

  & details > summary :is([class^="-icon-"], [class*=" -icon-"]),
  & .item :is([class^="-icon-"], [class*=" -icon-"]) {
    line-height: 1;
  }

  & details > summary::-webkit-details-marker {
    display: none;
  }

  /* The disclosure chevron rotates open (same technique as toggle-details). */
  & details > summary::before,
  & [role="treeitem"][aria-expanded] > .item::before {
    content: "";
    flex: none;
    inline-size: 1em;
    block-size: 1em;
    background: currentColor;
    -webkit-mask: var(--instui-icon-chevron-right) center / contain no-repeat;
    mask: var(--instui-icon-chevron-right) center / contain no-repeat;
    transition: transform 0.2s ease;
  }

  & details[open] > summary::before {
    transform: rotate(90deg);
  }

  & [role="treeitem"][aria-expanded="true"] > .item::before {
    transform: rotate(90deg);
  }

  & [role="treeitem"][aria-expanded] > .item:dir(rtl)::before {
    transform: rotate(180deg);
  }

  & [role="treeitem"][aria-expanded="true"] > .item:dir(rtl)::before {
    transform: rotate(90deg);
  }

  & details > summary:hover,
  & .item:hover {
    background: var(--instui-component-tree-browser-tree-button-hover-background-color);
    color: var(--instui-component-tree-browser-tree-button-hover-text-color);
  }

  & details > summary.-selected,
  & [role="treeitem"][aria-selected="true"] > .item,
  & .item[aria-selected="true"],
  & .item.-selected {
    background: var(--instui-component-tree-browser-tree-button-selected-background-color);
    color: var(--instui-component-tree-browser-tree-button-selected-text-color);
  }

  /* Nested lists indent; the leaf list carries no bullets. */
  & ul,
  & [role="group"] {
    margin: 0;
    padding-inline-start: var(--instui-component-tree-browser-tree-collection-base-spacing-medium);
    list-style: none;
  }

  &.-size-sm details > summary,
  &.-size-sm .item {
    padding: var(--instui-component-tree-browser-tree-button-base-spacing-small);
    font-size: var(--instui-component-tree-browser-tree-button-name-font-size-small);
  }

  &.-size-lg details > summary,
  &.-size-lg .item {
    padding: var(--instui-component-tree-browser-tree-button-base-spacing-large);
    font-size: var(--instui-component-tree-browser-tree-button-name-font-size-large);
  }

  @media (prefers-reduced-motion: reduce) {
    & details > summary::before,
    & [role="treeitem"][aria-expanded] > .item::before {
      transition: none;
    }
  }
}

