import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { readFile, readdir } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { extname, join, resolve } from 'node:path';
const require = createRequire(resolve('formats/components/package.json'));
const { chromium } = createRequire(require.resolve('automatica11y/package.json'))('playwright-core');
const root = resolve('a11y-report/2026-10-27T19-44-51.720Z/pages');
const server = createServer(async (req, res) => {
  if (req.url === '/favicon.ico') { res.writeHead(204).end(); return; }
  try {
    const path = join(root, new URL(req.url, 'http://localhost').pathname);
    const data = await readFile(path);
    res.setHeader('content-type', { '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript' }[extname(path)] ?? 'application/octet-stream');
    res.end(data);
  } catch (error) { console.error(error); res.writeHead(500).end('Fixture read failed'); }
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
let browser;
try {
  browser = await chromium.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: true });
  const files = (await readdir(root)).filter(name => name.endsWith('.html'));
  assert.equal(files.length, 6);
  for (const file of files) {
    const page = await browser.newPage();
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    await page.goto(`http://127.0.0.1:${server.address().port}/${file}`);
    const input = page.getByRole('spinbutton', { name: 'Quantity' });
    await input.focus();
    await input.press('ArrowUp');
    assert.equal(await input.inputValue(), '2');
    await input.press('ArrowDown');
    assert.equal(await input.inputValue(), '1');
    await input.press('Tab');
    assert.notEqual(await page.evaluate(() => document.activeElement?.tagName), 'BUTTON');
    assert.ok(await page.locator('.arrows button').evaluateAll(buttons => buttons.length === 2 && buttons.every(button => button.tabIndex === -1 && button.getAttribute('aria-hidden') === 'true')));
    assert.deepEqual(errors, []);
    console.log(`${file}: native increment/decrement and tab order passed`);
    await page.close();
  }
} finally {
  if (browser) await browser.close();
  await new Promise(resolve => server.close(resolve));
}
NODE

