/**
 * @component drawer-layout
 * @selector :host
 * @summary Additive host/wrapper glue for the drawer-layout web component; core layout/tray/content styles come from `@pantoken/components`.
 * @remarks The element composes `drawerLayoutCss` + `drawerLayoutTrayCss` + `drawerLayoutContentCss`, then layers these host-scoped rules for shadow-root sizing and overlay-state mirroring.
 * @remarks The interactions behavior (`initResponsiveOverlay`) controls host `open`/`should-overlay-tray`; this stylesheet mirrors those host states onto the internal `.layout` wrapper so the shared `@pantoken/components` selectors apply without reimplementation.
 * @part .layout — The flex row holding the tray and content.
 * @cssstate open — The tray shows; without it the tray is hidden.
 * @cssstate should-overlay-tray — The tray overlays content instead of shrinking it.
 * @slot tray — The drawer panel's content. The default slot holds the main content beside it.
 * @accessibility The tray only renders while the host carries the `open` attribute. The content pane carries `role="region"` (InstUI's DrawerLayout convention); name it with `aria-label`/`aria-labelledby` when context alone doesn't identify it.
 * @example
 * <instui-drawer-layout open placement="start">
 *   <nav slot="tray">Navigation</nav>
 *   <article>Main content</article>
 * </instui-drawer-layout>
 */
:host {
  display: block;
  block-size: 100%;
}

.layout {
  inline-size: 100%;
  block-size: 100%;
}

