/**
 * @component form-field
 * @summary A form-field wrapper: a label, its controls, and inline, required, or readonly layouts.
 * @remarks An error message stays hidden until the field's control is `:user-invalid` (after the user interacts) or you add the `-invalid` class. Use `-layout-inline` to put the label beside the controls and `-layout-stacked` to put it above. Also sets its own `gap` between the label, controls, and messages; chaining a `-gap-*` spacing utility modifier overrides that built-in value.
 * @modifier -inline — Inline layout (shorthand for `-layout-inline`).
 * @modifier -layout-inline — Inline layout: label beside the controls.
 * @modifier -layout-stacked — Stacked layout: label above the controls.
 * @modifier -label-align-start — Start-align the label text.
 * @modifier -label-align-end — End-align the label text.
 * @modifier -invalid — Invalid (error) state.
 * @modifier -readonly — Read-only state.
 * @modifier -v-align-top — Top-align the label with the controls.
 * @modifier -v-align-bottom — Bottom-align the label with the controls.
 * @part .label — The field label.
 * @part .controls — The control area beside or below the label.
 * @pseudo ::after — Renders the decorative required-field asterisk after the label text when the field is required.
 * @accessibility The `<label>` element wraps the control, so the label text names it natively; the required asterisk is decorative and should be hidden from assistive tech (aria-hidden), and the error message surfaces once the control is `:user-invalid` or you add the `-invalid` class.
 * @compat Contains its element styles with the CSS `@scope` at-rule; needs a recent Chromium, Firefox, or Safari.
 * @example -canvas-rce
 * <label class="pfx-form-field">
 *   <span class="label">Email address</span>
 *   <span class="controls"><input class="pfx-text-input" type="email" placeholder="[REDACTED_EMAIL]"></span>
 *   <div class="pfx-form-field-messages">
 *     <span class="pfx-form-field-message -type-hint">We'll never share it.</span>
 *     <span class="pfx-form-field-message -type-error">Enter a valid email address.</span>
 *   </div>
 * </label>
 * @example -automatica11y
 * ```html
 * <label class="pfx-form-field">
 *   <span class="label">Email address</span>
 *   <span class="controls"><input class="pfx-text-input" type="email" autocomplete="email" required data-a11y-trigger data-a11y-root></span>
 * </label>
 * ```
 * @example -docs
 * ```html
 * <label class="pfx-form-field">
 *   <span class="label">Display name</span>
 *   <span class="controls"><input class="pfx-text-input" type="text" autocomplete="nickname"></span>
 * </label>
 * ```
 * @structure
 * .pfx-form-field {
 *   .label {}
 *   .controls {
 *     .pfx-text-input {}
 *   }
 *   .pfx-form-field-messages {}
 * }
 * @related form-field-messages — Renders the field's hint, error, and success messages.
 * @related form-field-group — Groups related fields under a shared legend.
 */
.pfx-form-field {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-areas: "label" "controls" "messages";
  gap: var(--instui-component-form-field-layout-gap-inputs);
  color: var(--instui-component-form-field-layout-text-color);
  font-family: var(--instui-component-form-field-layout-font-family);
}

@scope (.pfx-form-field) {
  :scope {
    > .label {
      grid-area: label;
      color: var(--instui-component-form-field-layout-text-color);
      font-family: var(--instui-component-form-field-layout-font-family);
      font-weight: var(--instui-component-form-field-layout-font-weight);
      font-size: var(--instui-component-form-field-layout-font-size);
      line-height: var(--instui-component-form-field-layout-line-height);
    }

    > .controls {
      grid-area: controls;
    }
  }
}

/* Messages region — kept OUTSIDE @scope: the messages class shares the form-field prefix. */
.pfx-form-field > .pfx-form-field-messages {
  grid-area: messages;
}

/* Client-side validation: an error message stays hidden until the field's control is :user-invalid
   (after the user has interacted), per MDN guidance; then it shows. The explicit -invalid class on the
   control (and a standalone .instui-form-field-messages outside a field) are unaffected. */
.pfx-form-field .pfx-form-field-message.-type-error,
.pfx-form-field .pfx-form-field-message.-type-new-error {
  display: none;
}

.pfx-form-field:has(:user-invalid) .pfx-form-field-message.-type-error,
.pfx-form-field:has(:user-invalid) .pfx-form-field-message.-type-new-error,
.pfx-form-field.-invalid .pfx-form-field-message.-type-error,
.pfx-form-field.-invalid .pfx-form-field-message.-type-new-error {
  display: inline-flex;
}

/* Required indicator: native [required] control OR the -required class; decorative (aria-hidden). */
.pfx-form-field:is(.-required, :has(:required)) .label::after {
  content: "*";
  margin-inline-start: 0.25rem;
  color: var(--instui-component-form-field-layout-asterisk-color);
}

.pfx-form-field.-readonly .label {
  color: var(--instui-component-form-field-layout-readonly-text-color);
}

.pfx-form-field.-layout-stacked {
  grid-template-columns: 1fr;
  grid-template-areas: "label" "controls" "messages";
}

.pfx-form-field.-layout-inline {
  grid-template-columns: auto 1fr;
  grid-template-areas: "label controls" ". messages";
  align-items: center;
  column-gap: var(--instui-component-form-field-layout-gap-primitives);
}

.pfx-form-field.-layout-inline.-v-align-top {
  align-items: start;
}

.pfx-form-field.-layout-inline.-v-align-bottom {
  align-items: end;
}

.pfx-form-field.-layout-inline.-label-align-start .label {
  text-align: start;
}

.pfx-form-field.-layout-inline.-label-align-end .label {
  text-align: end;
}

.pfx-form-field.-inline {
  display: inline-grid;
  inline-size: auto;
}

