  assert.equal(files.length, 6);
  for (const file of files) {
    const page = await browser.newPage();
    const errors = [];
    page.on("pageerror", error => errors.push(error.message));
    await page.goto(`${base}/${file}`);
    const input = page.locator("input");
    const error = page.locator("#audit-email-error");
    assert.equal(await input.getAttribute("aria-invalid"), "true");
    assert.equal(await input.getAttribute("aria-describedby"), "audit-email-hint audit-email-error");
    assert.equal(await error.isVisible(), true);
    const client = await page.context().newCDPSession(page);
    const { nodes } = await client.send("Accessibility.getFullAXTree");
    const field = nodes.find(node => node.role?.value === "textbox");
    assert.ok(field.description?.value.includes("Enter a valid email address."));
    if (file.includes("canvas-dark")) await page.screenshot({ path: "/Users/dwahl/.copilot/session-state/9347a925-530d-4721-9964-9f9d5f3aa58a/files/form-field-verification.png" });
    await error.evaluate(element => { element.hidden = true; });
    assert.equal(await error.isVisible(), false);
    await input.fill("");
    await input.press("Tab");
    assert.equal(await error.isVisible(), true);
    await error.evaluate(element => { element.hidden = false; });
    await input.fill("[REDACTED_EMAIL]");
    assert.equal(await input.getAttribute("aria-invalid"), "false");
    assert.equal(await input.getAttribute("aria-describedby"), "audit-email-hint");
    assert.equal(await error.isVisible(), false);
    assert.deepEqual(errors, []);
    console.log(`${file}: visible associated error, Chromium description, correction, and hidden precedence passed`);
    await client.detach();
    await page.close();
  }
  const page = await browser.newPage();
  await page.goto(`${base}/${files[0]}?plain=1`);
  const input = page.locator("input");
  await input.fill("");
  await input.press("Tab");
  assert.equal(await input.getAttribute("aria-invalid"), null);
  assert.equal(await input.getAttribute("aria-describedby"), "audit-email-hint");
  console.log("Without the opt-in marker, application-owned ARIA remains untouched.");
  await page.goto(`${base}/${files[0]}?form=1`);
  await page.locator("form").evaluate(form => form.reset());
  assert.equal(await input.getAttribute("aria-invalid"), "false");
  await input.evaluate(element => { element.value = ""; });
  await page.getByRole("button", { name: "Save" }).click();
  assert.equal(await input.getAttribute("aria-invalid"), "true");
  assert.equal(await page.locator("#audit-email-error").isVisible(), true);
  await page.locator("form").evaluate(form => form.reset());
  assert.equal(await input.inputValue(), "[REDACTED_EMAIL]");
  assert.equal(await input.getAttribute("aria-invalid"), "false");
  assert.equal(await page.locator("#audit-email-error").isVisible(), false);
  console.log("Native submission and form reset synchronize validation state.");
  await page.close();
} finally {
  if (browser) await browser.close();
  await new Promise(resolve => server.close(resolve));
}

