+  page.on("pageerror", error => errors.push(error.message));
+  await page.goto(`http://127.0.0.1:${server.address().port}`);
+  const native = await page.evaluate(async () => {
+    const dialog = document.createElement("dialog");
+    dialog.innerHTML = "<button>Inside</button>";
+    document.body.append(dialog);
+    const states = [];
+    dialog.showModal();
+    states.push({ operation: "showModal", open: dialog.open, modal: dialog.matches(":modal") });
+    dialog.removeAttribute("open");
+    states.push({ operation: "remove open", open: dialog.open, modal: dialog.matches(":modal") });
+    await new Promise(resolve => setTimeout(resolve, 0));
+    states.push({ operation: "after mutation", open: dialog.open, modal: dialog.matches(":modal") });
+    dialog.setAttribute("open", "");
+    dialog.close();
+    states.push({ operation: "restore and close", open: dialog.open, modal: dialog.matches(":modal") });
+    dialog.remove();
+    return states;
+  });
