+  assert.equal(state.modal, fixed);
+  assert.equal(state.focusInside, fixed);
+  await page.keyboard.press("Escape");
+  assert.equal(await page.locator("#modal").evaluate(dialog => dialog.open), !fixed);
+  console.log(fixed ? "Native modal activation, focus entry, and Escape passed." : "Reproduced: open attribute without top layer, focus entry, or Escape dismissal.");
+  assert.deepEqual(errors, []);
+} finally {
+  if (browser) await browser.close();
+  await new Promise(resolve => server.close(resolve));
+}
