import assert from "node:assert/strict";
import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { resolve, extname, sep } from "node:path";
import { pathToFileURL } from "node:url";

const require = createRequire(resolve("formats/components/package.json"));
const { chromium } = createRequire(require.resolve("automatica11y/package.json"))("playwright-core");
const { parseCssDocs } = await import(require.resolve("@cssdoc/core"));
const { menu } = await import(pathToFileURL(resolve("formats/components/src/components/menu/index.ts")));
const { collectExamples, expandCases, renderPage } = await import(pathToFileURL(resolve("formats/components/scripts/audit-accessibility.ts")));
const cases = expandCases(collectExamples(parseCssDocs(menu.rules("instui-")), ["menu"]));
const pages = new Map(cases.map(item => [`/${item.id}.html`, renderPage(item).replace(/<script>[\s\S]*?<\/script>/u, "")]));
const assets = [
  ["/assets/interactions/", resolve("formats/interactions/dist")],
  ["/assets/components/", resolve("formats/components/dist")],
  ["/assets/tokens/", resolve("formats/css/dist")],
  ["/assets/assets/", resolve("formats/components/assets")],
];
const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, "http://localhost");
    const html = pages.get(url.pathname);
    if (html) {
      res.setHeader("content-type", "text/html");
      res.end(url.searchParams.has("plain") ? html.replace(" data-menu-navigation", "") : html);
      return;
    }
    if (url.pathname === "/favicon.ico") {
      res.writeHead(204).end();
      return;
    }
    const route = assets.find(([prefix]) => url.pathname.startsWith(prefix));
    if (!route) { res.writeHead(404).end("Unknown fixture"); return; }
    const [prefix, root] = route;
    const path = resolve(root, url.pathname.slice(prefix.length));
    if (!path.startsWith(root + sep)) { res.writeHead(400).end("Invalid asset path"); return; }
    res.setHeader("content-type", { ".css": "text/css", ".js": "text/javascript", ".woff2": "font/woff2" }[extname(path)] ?? "application/octet-stream");
    res.end(await readFile(path));
  } catch (error) {
    console.error(error);
    res.writeHead(500).end("Fixture read failed");
  }
});
await new Promise(resolve => server.listen(0, "127.0.0.1", resolve));
let browser;
try {
  browser = await chromium.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", headless: true });
  const base = `http://127.0.0.1:${server.address().port}`;
  assert.equal(pages.size, 6);
  for (const [file] of pages) {
    const page = await browser.newPage();
    const errors = [];
    page.on("pageerror", error => errors.push(error.message));
    await page.goto(`${base}${file}`);
    const trigger = page.getByRole("button", { name: "Actions", exact: true });
    const menu = page.locator('[role="menu"]');
    const edit = menu.locator(".item").nth(0);
    const del = menu.locator(".item").nth(1);
    const expanded = async value => page.waitForFunction(value =>
      document.querySelector("[popovertarget]").getAttribute("aria-expanded") === value,
    String(value));
    const focused = async label => page.waitForFunction(label => document.activeElement?.textContent.trim() === label, label);
    await trigger.focus();
    await trigger.press("Enter");
    await expanded(true);
    await focused("Edit");
    console.log(file, "rest style", await edit.evaluate(element => ({
      foreground: getComputedStyle(element).color,
      background: getComputedStyle(element).backgroundColor,
      parentBackground: getComputedStyle(element.parentElement).backgroundColor,
    })));
    await edit.press("ArrowUp");
    await focused("Delete");
    await del.press("ArrowDown");
    await focused("Edit");
    await edit.press("End");
    await focused("Delete");
    await del.press("Home");
    await focused("Edit");
    await edit.press("d");
    await focused("Delete");
    assert.equal(await menu.locator('[tabindex="0"]').count(), 1);
    await menu.evaluate(element => { element.dir = "rtl"; });
    await del.press("ArrowDown");
    await focused("Edit");
    await edit.press("Escape");
    await expanded(false);
    await focused("Actions");

    await trigger.press("ArrowUp");
    await expanded(true);
    await focused("Delete");
    await del.evaluate(element => {
      element.dataset.clicks = "0";
      element.addEventListener("click", () => { element.dataset.clicks = String(Number(element.dataset.clicks) + 1); });
    });
    await del.press(" ");
    await expanded(false);
    assert.equal(await del.getAttribute("data-clicks"), "1");
    await focused("Actions");

    await page.evaluate(() => {
      const menu = document.querySelector('[role="menu"]');
      menu.insertAdjacentHTML("beforeend", '<button class="item -disabled" role="menuitem" type="button" aria-disabled="true">Unavailable</button><button class="item" type="button" role="menuitemcheckbox" aria-checked="false">Show grid</button>');
      const disabled = menu.querySelector('[aria-disabled="true"]');
      disabled.dataset.clicks = "0";
      disabled.addEventListener("click", () => { disabled.dataset.clicks = "1"; });
      const check = menu.querySelector('[role="menuitemcheckbox"]');
      check.addEventListener("click", () => check.setAttribute("aria-checked", String(check.getAttribute("aria-checked") !== "true")));
    });
    await trigger.press("ArrowDown");
    await focused("Edit");
    await edit.press("ArrowDown");
    await del.press("ArrowDown");
    await focused("Unavailable");
    const disabled = page.getByRole("menuitem", { name: "Unavailable" });
    await disabled.press("Enter");
    await disabled.press(" ");
    await disabled.evaluate(element => element.click());
    assert.equal(await disabled.getAttribute("data-clicks"), "0");
    await expanded(true);
    await disabled.press("ArrowDown");
    await focused("Show grid");
    const check = page.getByRole("menuitemcheckbox", { name: "Show grid" });
    await check.press(" ");
    assert.equal(await check.getAttribute("aria-checked"), "true");
    await expanded(true);
    await check.press("Enter");

