const segments = (): HTMLElement[] => [...strip.querySelectorAll<HTMLElement>(":scope > label")];
const isOverflown = options.isOverflown ?? true;
let arrowWidth = 0;
if (options.size) {
  host.classList.remove("-size-sm", "-size-md", "-size-lg");
  host.classList.add(`-size-${options.size}`);
}

const first =
  radios().find((radio) => radio.checked) ?? radios().find((radio) => !radio.disabled);
if (first) first.checked = true;

for (const radio of radios()) {
  const iconClass = [...radio.classList].find((className) => className.startsWith("-icon-"));
  if (iconClass) radio.closest<HTMLElement>("label")?.classList.add(iconClass);
}

const bounds = (): { left: number; right: number; rtl: boolean } => {
  const rect = strip.getBoundingClientRect();
  const rtl = getComputedStyle(strip).direction === "rtl";
  return {
    left: rect.left + (startButton?.hidden ? 0 : arrowWidth),
    right: rect.right - (endButton?.hidden ? 0 : arrowWidth),
    rtl,
  };
};

const applyReserves = (): void => {
  if (!startButton || !endButton) return;
  strip.style.setProperty(
    "--pantoken-segmented-start-reserve",
    startButton.hidden ? "0px" : `${arrowWidth}px`,
  );
  strip.style.setProperty(
    "--pantoken-segmented-end-reserve",
    endButton.hidden ? "0px" : `${arrowWidth}px`,
  );
};

const updateArrows = (): void => {
  if (!startButton || !endButton) return;
  const { left, right, rtl } = bounds();
  if (!rtl) {
    startButton.hidden = strip.scrollLeft <= 1;
    endButton.hidden = strip.scrollLeft + strip.clientWidth >= strip.scrollWidth - 1;
  } else {
    const items = segments();
    const firstRect = items[0]?.getBoundingClientRect();
    const lastRect = items[items.length - 1]?.getBoundingClientRect();
    startButton.hidden = !lastRect || lastRect.right <= right + 1;
    endButton.hidden = !firstRect || firstRect.left >= left - 1;
  }
  applyReserves();

