import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
const root = 'a11y-report/2026-10-27T23-12-44.670Z';
const suites = ['pages-rebrand-light','pages-rebrand-dark','pages-canvas-light','pages-canvas-dark','pages-canvasHighContrast-light','pages-canvasHighContrast-dark','npm-tooltip'];
const counts = { targets:0, configurations:0, coverageNotices:0, axeViolations:0, axeReviews:0, ibmViolations:0, ibmReviews:0, flags:0, interactions:{}, computed:{}, conditions:{}, escape:0, hover:0, reflow:0 };
const reviews = {};
const measurements = [];
for (const suite of suites) {
  const result = JSON.parse(readFileSync(`${root}/${suite}/results.json`, 'utf8'));
  counts.coverageNotices += result.outcome.coverage.length;
  for (const target of result.targets) {
    assert.equal(target.status, 'ran', `${suite}/${target.id}`);
    counts.targets++;
    for (const archetype of Object.values(target.archetypes)) {
      assert.equal(archetype.status, 'ran');
      for (const config of archetype.configs) {
        counts.configurations++;
        for (const [engine, data] of Object.entries(config.tiers.rules.engines)) {
          assert.equal(data.status, 'ran');
          assert.equal(data.violations.length, 0, `${target.id}/${engine}`);
          counts[`${engine}Violations`] += data.violations.length;
          counts[`${engine}Reviews`] += data.incomplete.length;
          for (const review of data.incomplete) reviews[`${engine}/${review.id ?? review.ruleId}`] = (reviews[`${engine}/${review.id ?? review.ruleId}`] ?? 0) + 1;
        }
        assert.equal(config.tiers.vsr.status, 'ran');
        counts.flags += config.tiers.vsr.flags.length;
        for (const tier of ['interactions','computed','conditions']) {
          const data = config.tiers[tier];
          if (!data) continue;
          assert.equal(data.status, 'ran');
          for (const check of data.checks) {
            assert.ok(['pass','not-applicable'].includes(check.result), `${target.id}/${check.name}: ${check.result}`);
            counts[tier][check.result] = (counts[tier][check.result] ?? 0) + 1;
            if (check.name === 'escape-dismisses') { assert.equal(check.result, 'pass'); counts.escape++; }
            if (check.name === 'content-reachable-on-hover') { assert.equal(check.result, 'pass'); counts.hover++; }
            if (check.name === 'reflow-at-320px') { assert.equal(check.result, 'pass'); counts.reflow++; }
            if (tier === 'computed') measurements.push({target:target.id, check:check.name, detail:check.detail});
          }
        }
      }
    }
  }
}
assert.equal(counts.targets, 12);
assert.equal(counts.configurations, 18);
assert.equal(counts.escape, 6);
assert.equal(counts.hover, 6);
assert.equal(counts.reflow, 12);
assert.equal(counts.flags, 0);
assert.equal(counts.coverageNotices, 18);
console.log(JSON.stringify({counts,reviews,measurements},null,2));
