node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {readFileSync, realpathSync} from 'node:fs';
import {createRequire} from 'node:module';
import {resolve, sep} from 'node:path';
const root=resolve('a11y-report/2026-10-27T23-21-35.359Z/pages');
const require=createRequire(realpathSync('formats/components/node_modules/automatica11y/package.json'));
const {chromium}=require('playwright-core');
const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
try {
 const page=await browser.newPage();
 const errors=[];
 page.on('pageerror',error=>errors.push(error.message));
 await page.route('http://pill.test/**',async route=>{
  const file=resolve(root,`.${decodeURIComponent(new URL(route.request().url()).pathname)}`);
  assert.ok(file.startsWith(root+sep));
  await route.fulfill({path:file});
 });
 for(const theme of ['rebrand','canvas','canvashighcontrast']) for(const scheme of ['light','dark']) {
  for(const width of [320,1280]) {
   await page.setViewportSize({width,height:800});
   await page.goto(`http://pill.test/pill-1-${theme}-${scheme}.html`);
   await page.evaluate(()=>document.fonts.ready);
   const geometry=await page.locator('.instui-pill').evaluateAll(nodes=>({
    scrollWidth:document.documentElement.scrollWidth,
    labels:nodes.map(n=>n.textContent.trim()),
    boxes:nodes.map(n=>{const r=n.getBoundingClientRect();return {left:r.left,right:r.right,top:r.top,width:r.width,height:r.height};})
   }));
   assert.deepEqual(geometry.labels,['Published','Draft','In review','Stale','Blocked','Pastel']);
   assert.ok(geometry.scrollWidth<=width,`${theme}/${scheme}/${width}: ${geometry.scrollWidth}`);
   assert.ok(geometry.boxes.every(r=>r.left>=0 && r.right<=width && r.width>0 && r.height>0));
   const rows=new Set(geometry.boxes.map(r=>Math.round(r.top)));
   assert.ok(width===320 ? rows.size>1 : rows.size===1);
  }
  console.log(`${theme}/${scheme}: all six labels wrap at 320px and retain one row at 1280px.`);
 }
 assert.deepEqual(errors,[]);
} finally { await browser.close(); }
NODE

