import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const root='a11y-report/2026-10-27T23-21-35.359Z';
const totals={targets:0,axeViolations:0,axeReviews:0,ibmViolations:0,ibmReviews:0,reflow:0,conditions:{},flags:0};
for(const theme of ['rebrand','canvas','canvasHighContrast']) for(const scheme of ['light','dark']) {
 const r=JSON.parse(readFileSync(`${root}/pages-${theme}-${scheme}/results.json`,'utf8'));
 assert.equal(r.targets.length,1);
 const t=r.targets[0]; assert.equal(t.status,'ran'); totals.targets++;
 for(const a of Object.values(t.archetypes)) for(const c of a.configs) {
  for(const [engine,data] of Object.entries(c.tiers.rules.engines)) {
   assert.equal(data.status,'ran'); assert.equal(data.violations.length,0);
   totals[`${engine}Violations`]+=data.violations.length; totals[`${engine}Reviews`]+=data.incomplete.length;
  }
  for(const check of c.tiers.conditions.checks) {
   assert.ok(['pass','not-applicable'].includes(check.result),check.name);
   totals.conditions[check.result]=(totals.conditions[check.result]??0)+1;
   if(check.name==='reflow-at-320px') {assert.equal(check.result,'pass');totals.reflow++;}
  }
  totals.flags+=c.tiers.vsr.flags.length;
 }
}
assert.equal(totals.reflow,6);assert.equal(totals.flags,0);console.log(JSON.stringify(totals,null,2));
