    const content='<h2>Course content</h2><p>Readable course content stays inside its pane.</p>';
    const attrs=`placement="${placement}" ${state==='open'?'open':''}`;
    document.querySelector('main').innerHTML=`<div id="frame" style="inline-size:1200px;block-size:240px">${mode==='css'?`<div class="instui-drawer-layout" ${attrs}>${tray}<div class="content" role="region" aria-label="Course content">${content}</div></div>`:`<instui-drawer-layout ${attrs} tray-label="Course panel" content-label="Course content">${tray}${content}</instui-drawer-layout>`}</div>`;
   },{mode,dir,placement,state});
   for(const width of [1200,288]) {
    await page.locator('#frame').evaluate((frame,width)=>frame.style.inlineSize=`${width}px`,width);
    await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
    const result=await page.locator('#frame').evaluate((frame,mode)=>{
     const host=frame.firstElementChild;
     const layout=mode==='wc'?host.shadowRoot.querySelector('.layout'):host;
     const content=layout.querySelector('.content');const tray=layout.querySelector('.tray');
     return {frame:frame.getBoundingClientRect().toJSON(),content:content.getBoundingClientRect().toJSON(),minimum:getComputedStyle(content).minInlineSize,tray:tray?{box:tray.getBoundingClientRect().toJSON(),display:getComputedStyle(tray).display,position:getComputedStyle(tray).position}:null,manual:host.hasAttribute('should-overlay-tray')};
    },mode);
    const label=`${theme}/${scheme}/${mode}/${dir}/${placement}/${state}/${width}`;
    assert.ok(result.content.left>=result.frame.left-0.1&&result.content.right<=result.frame.right+0.1,label);
    assert.equal(result.minimum,width===288?'0px':'768px',label);
    if(mode==='wc') assert.equal(result.manual,false,`${label}: must exercise automatic CSS, not the manual override`);
    if(state==='closed') assert.equal(result.tray.display,'none',label);
    if(state==='open') {
     assert.equal(result.tray.position,width===288?'absolute':'static',label);
     if(width===288) {
      const startIsLeft=(placement==='start')===(dir==='ltr');
      assert.ok(Math.abs((startIsLeft?result.tray.box.left:result.tray.box.right)-(startIsLeft?result.frame.left:result.frame.right))<0.1,label);
     }
    }
    cases++;
   }
  }
  assert.deepEqual(errors,[]);await page.close();
  console.log(`${theme}/${scheme}: CSS and WC, LTR/RTL, both sides, open/closed/absent tray, desktop and nested narrow containers passed.`);
 }
 console.log(`${cases} production drawer geometry cases passed without manual overlay overrides.`);
} finally {await browser.close();}
