/**
 * @component table
 * @selector .pfx-table
 * @summary A styled data table for `th` and `td` plus an optional caption, with hover, fixed, and stacked-card layouts.
 * @remarks For `-layout-stacked`, pure CSS can't pull each column header's text into its cell, so give every cell a `data-label` and the stacked card shows it via `::before`. See the `table.head`, `table.body`, `table.row`, `table.cell`, `table.col-header`, and `table.row-header` members for the individual parts.
 * @modifier -hover — Highlight rows on hover. @affects table.row — Reserves and colours the row's hover border.
 * @modifier -layout-fixed — Fixed table layout (equal-width columns).
 * @modifier -layout-stacked — Stack each row as a card, via a per-cell `data-label`. @affects table.head @affects table.body @affects table.row @affects table.cell @affects table.col-header @affects table.row-header — Stacks each part as a block and hides/labels the header accordingly.
 * @part caption — An optional table caption.
 * @accessibility Label the table with a `<caption>`, mark column headers `<th scope="col">` and row headers `<th scope="row">`, and in `-layout-stacked` give every cell a `data-label` since the header row is visually hidden.
 * @example -canvas-rce -docs
 * ```html
 * <table class="pfx-table -hover">
 *   <caption>Top-rated films</caption>
 *   <thead>
 *     <tr>
 *       <th scope="col">Rank</th>
 *       <th scope="col">Title</th>
 *       <th scope="col">Year</th>
 *       <th scope="col">Rating</th>
 *     </tr>
 *   </thead>
 *   <tbody>
 *     <tr>
 *       <th scope="row">1</th>
 *       <td>The Shawshank Redemption</td>
 *       <td>1994</td>
 *       <td>9.3</td>
 *     </tr>
 *     <tr>
 *       <th scope="row">2</th>
 *       <td>The Godfather</td>
 *       <td>1972</td>
 *       <td>9.2</td>
 *     </tr>
 *     <tr>
 *       <th scope="row">3</th>
 *       <td>The Godfather: Part II</td>
 *       <td>1974</td>
 *       <td>9.0</td>
 *     </tr>
 *   </tbody>
 * </table>
 * ```
 * @structure
 * .pfx-table.-hover {
 *   caption {}
 *   thead {
 *     th {}
 *   }
 *   tbody {
 *     tr {
 *       td, th[scope="row"] {}
 *     }
 *   }
 * }
 * @example -automatica11y
 * ```html
 * <table class="pfx-table -hover">
 *   <caption>Top-rated films</caption>
 *   <thead>
 *     <tr>
 *       <th scope="col">Rank</th>
 *       <th scope="col">Title</th>
 *       <th scope="col">Year</th>
 *       <th scope="col">Rating</th>
 *     </tr>
 *   </thead>
 *   <tbody>
 *     <tr>
 *       <th scope="row">1</th>
 *       <td>The Shawshank Redemption</td>
 *       <td>1994</td>
 *       <td>9.3</td>
 *     </tr>
 *     <tr>
 *       <th scope="row">2</th>
 *       <td>The Godfather</td>
 *       <td>1972</td>
 *       <td>9.2</td>
 *     </tr>
 *     <tr>
 *       <th scope="row">3</th>
 *       <td>The Godfather: Part II</td>
 *       <td>1974</td>
 *       <td>9.0</td>
 *     </tr>
 *   </tbody>
 * </table>
 * ```
 */
@scope (.pfx-table) {
  & {
    border-collapse: collapse;
    width: 100%;
    background: var(--instui-component-table-background);
    color: var(--instui-component-table-color);
    font-family: var(--instui-component-table-font-family);
    font-size: var(--instui-component-table-font-size);
  }

  & caption {
    text-align: start;
    padding: var(--instui-component-table-cell-padding-vertical)
      var(--instui-component-table-cell-padding-horizontal);
    color: var(--instui-component-table-col-header-color);
    font-weight: var(--instui-component-table-head-font-weight);
  }

  /* layout="fixed": columns size to the header/first row, not content (InstUI `layout`). */
  &.-layout-fixed {
    table-layout: fixed;
  }

  /* layout="stacked": the table itself just stops being a table box; see the head/body/row/cell/
   col-header/row-header members for how each part restacks. */
  &.-layout-stacked {
    display: block;
    width: auto;
  }
}

