node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {readFileSync,realpathSync} from 'node:fs';
import {createRequire} from 'node:module';
import {resolve,sep} from 'node:path';
const root=resolve('a11y-report/2026-10-27T23-21-35.359Z/pages');
const require=createRequire(realpathSync('formats/components/node_modules/automatica11y/package.json'));
const {chromium}=require('playwright-core');
const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
try {
 for(const theme of ['rebrand','canvas','canvashighcontrast']) for(const scheme of ['light','dark']) {
  const page=await browser.newPage({viewport:{width:320,height:800}});
  await page.route('http://table.test/**',async route=>{
   const file=resolve(root,`.${decodeURIComponent(new URL(route.request().url()).pathname)}`);assert.ok(file.startsWith(root+sep));await route.fulfill({path:file});
  });
  await page.goto(`http://table.test/pill-1-${theme}-${scheme}.html`);
  const original=readFileSync(`a11y-report/2026-10-27T16-21-38.658Z/pages/table-1-${theme}-${scheme}.html`,'utf8');
  await page.evaluate(original=>{
   const table=new DOMParser().parseFromString(original,'text/html').querySelector('table');
   const main=document.querySelector('main');
   main.innerHTML='<h2 data-context>Film rankings and course information</h2><p data-context>Read the film rankings in the table below. This surrounding explanation must wrap within the narrow viewport.</p><div data-context><button class="instui-button">Filter</button> <button class="instui-button">Export</button></div>';
   main.append(table);
   main.insertAdjacentHTML('beforeend','<p data-context>Further course information also wraps below the table instead of following its minimum width.</p>');
  },original);
  const measurements=await page.evaluate(()=>{
   const box=n=>{const r=n.getBoundingClientRect();return {left:r.left,right:r.right,width:r.width};};
   const table=document.querySelector('table');
   const caption=table.caption;
   const range=document.createRange();range.selectNodeContents(caption);
   return {pageWidth:document.documentElement.scrollWidth,table:box(table),caption:box({getBoundingClientRect:()=>range.getBoundingClientRect()}),context:[...document.querySelectorAll('[data-context]')].map(box),cells:[...table.querySelectorAll('th,td')].map(n=>({box:box(n),width:n.scrollWidth,height:n.scrollHeight,visibleHeight:n.clientHeight})),headers:[...table.querySelectorAll('thead th')].map(n=>n.scope)};
  });
  assert.ok(measurements.context.every(r=>r.left>=0&&r.right<=320));
  assert.ok(measurements.caption.left>=0&&measurements.caption.right<=320);
  assert.ok(measurements.cells.every(c=>c.box.width<320&&c.width<320&&c.height<=c.visibleHeight+1));
  assert.deepEqual(measurements.headers,['col','col','col','col']);
  await page.evaluate(()=>window.scrollTo({left:document.documentElement.scrollWidth,behavior:'instant'}));
  const right=await page.locator('table').evaluate(table=>table.getBoundingClientRect().right);
  assert.ok(right<=320.1);
  console.log(`${theme}/${scheme}: page ${measurements.pageWidth}px; context and caption fit 320px, cell contents fit, and the final column is reachable.`);
  await page.close();
 }
} finally {await browser.close();}
