+        const components = resolve(repo, "formats/components/dist/components.css");
+        const file = path === "/assets/components/components.css" ? components : resolve(root, `.${path}`);
+        assert.ok(file === components || file.startsWith(root + sep));
+        await route.fulfill({ path: file });
+      });
+      await page.goto(`http://table.test/table-1-${theme}-${scheme}.html`);
+      await page.evaluate(() => document.fonts.ready);
+      const region = page.locator('[role="region"][tabindex="0"]');
+      const table = page.locator(".instui-table.-layout-responsive");
+      const container = page.locator(".instui-container");
+      await page.keyboard.press("Tab");
+      assert.equal(await region.evaluate((node) => node === document.activeElement), true);
+      const ring = () => region.evaluate((node) => {
+        const style = getComputedStyle(node);
+        return {
+          color: style.outlineColor, width: style.outlineWidth, style: style.outlineStyle,
+          offset: style.outlineOffset, animations: node.getAnimations().length,
+        };
+      });
+      const immediate = await ring();
+      await region.evaluate((node) => Promise.all(node.getAnimations().map((animation) => animation.finished)));
+      const settled = await ring();
+      await page.emulateMedia({ forcedColors: "active" });
+      console.log(`${theme}/${scheme} focus:`, JSON.stringify({ immediate, settled, forced: await ring() }));
+      await page.emulateMedia({ forcedColors: "none" });
+      for (const dir of ["ltr", "rtl"]) {
+        await page.evaluate((dir) => document.documentElement.dir = dir, dir);
+        for (const viewport of [320, 1280]) {
+          await page.setViewportSize({ width: viewport, height: 900 });
+          await container.evaluate((node) => node.style.removeProperty("inline-size"));
+          const geometry = await table.evaluate((node) => ({
+            display: getComputedStyle(node).display,
+            right: node.getBoundingClientRect().right,
+            page: document.documentElement.scrollWidth,
+            labels: [...node.querySelectorAll("tbody td")].map((cell) => ({
+              label: cell.dataset.label,
+              before: getComputedStyle(cell, "::before").content,
+            })),
+          }));
+          assert.equal(geometry.display, viewport === 320 ? "block" : "table");
+          assert.ok(geometry.page <= viewport);
+          if (viewport === 320) assert.ok(geometry.labels.every((cell) => cell.before.includes(cell.label)));
+          cases++;
+        }
+        for (const width of [288, 767, 768, 769]) {
+          await container.evaluate((node, width) => node.style.inlineSize = `${width}px`, width);
+          assert.equal(await table.evaluate((node) => getComputedStyle(node).display), width < 768 ? "block" : "table");
+          cases++;
+        }
+      }
+      await page.setViewportSize({ width: 320, height: 900 });
+      await container.evaluate((node) => node.style.removeProperty("inline-size"));
+      await page.evaluate(() => document.documentElement.dir = "ltr");
+      const snapshot = await table.ariaSnapshot();
+      assert.ok(snapshot.includes('table "Responsive film ratings"'), snapshot);
+      assert.ok(snapshot.includes('columnheader "Title"'), snapshot);
+      assert.ok(snapshot.includes('columnheader "Year"'), snapshot);
+      assert.ok(snapshot.includes('columnheader "Rating"'), snapshot);
+      await table.locator("tbody td").first().evaluate((cell) => {
+        cell.insertAdjacentHTML("beforeend", '<table class="instui-table" id="nested"><caption>Nested data</caption><thead><tr><th scope="col">Item</th></tr></thead><tbody><tr><td>Value</td></tr></tbody></table>');
+      });
+      assert.equal(await page.locator("#nested thead").evaluate((node) => getComputedStyle(node).position), "static");
+      assert.equal(await page.locator("#nested td").evaluate((node) => getComputedStyle(node).display), "table-cell");
+      assert.deepEqual(errors, []);
+      await context.close();
+      console.log(`${theme}/${scheme}: responsive geometry, labels, accessibility hierarchy, and nested-table isolation passed with page JavaScript disabled.`);
+    }
+  }
+  console.log(`${cases} table viewport/container geometry cases passed.`);
+} finally {
+  await browser.close();
+}
*** End Patch

