+        const style = getComputedStyle(part);
+        const clip = part.getBoundingClientRect();
+        const host = part.parentElement.getBoundingClientRect();
+        const range = document.createRange();
+        range.setStart(part.firstChild, 0);
+        range.setEnd(part.firstChild, 1);
+        const glyph = range.getBoundingClientRect();
+        const canvas = document.createElement("canvas");
+        const ctx = canvas.getContext("2d");
+        ctx.font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;
+        const ink = ctx.measureText(part.textContent.trim()[0]);
+        return {
+          text: part.textContent.trim(), width: clip.width, over: part.scrollWidth - part.clientWidth,
+          visibleInk: Math.max(0, Math.min(glyph.left + ink.actualBoundingBoxRight, clip.right) - Math.max(glyph.left - ink.actualBoundingBoxLeft, clip.left)),
+          verticallyContained: clip.top >= host.top && clip.bottom <= host.bottom,
+          letterSpacing: style.letterSpacing,
+        };
+      }));
+      const before = await measure();
+      const accessibleBefore = await page.locator("main").ariaSnapshot();
+      await page.evaluate(() => {
+        const style = document.createElement("style");
+        style.textContent = "* { line-height: 1.5 !important; letter-spacing: 0.12em !important; word-spacing: 0.16em !important; } p { margin-bottom: 2em !important; }";
+        document.head.append(style);
+      });
+      const after = await measure();
+      for (let i = 0; i < before.length; i++) {
+        assert.ok(after[i].over > before[i].over + 1);
+        assert.ok(Math.abs(after[i].width - before[i].width) < 0.1);
+        assert.ok(Math.abs(after[i].visibleInk - before[i].visibleInk) < 0.1, JSON.stringify({before: before[i], after: after[i]}));
+        assert.ok(before[i].verticallyContained && after[i].verticallyContained);
+      }
+      assert.equal(await page.locator("main").ariaSnapshot(), accessibleBefore);
+      assert.ok(accessibleBefore.includes("Miguel Sanchez"));
+      console.log(`${theme}/${scheme}:`, JSON.stringify({before, after, accessibilityTreeUnchanged: true}));
+      await context.close();
+    }
+  }
+} finally {
+  await browser.close();
+}
