/**
 * @component toggle-details
 * @selector .pfx-toggle-details
 * @summary A styled native `<details>` disclosure with a rotating chevron.
 * @remarks Built on the native `<details>` element, so the browser drives open and close plus keyboard support; the CSS only hides the default marker and supplies the rotating chevron.
 * @modifier -variant-filled — Filled (surface) variant.
 * @modifier -chevron-end — Place the chevron after the summary.
 * @modifier -size-sm — Small.
 * @modifier -size-lg — Large.
 * @pseudo ::before — Draws the summary's disclosure chevron, a masked glyph that rotates to point down when the disclosure is open.
 * @cssstate open
 * @example -canvas-rce
 * <details class="pfx-toggle-details" open>
 *   <summary>What ships in this package?</summary>
 *   Class-based component styles, built from the Instructure tokens, plus a prose layer.
 * </details>
 * @example -automatica11y
 * ```html
 * <details class="pfx-toggle-details" data-a11y-root>
 *   <summary data-a11y-trigger>What ships in this package?</summary>
 *   Class-based component styles and a prose layer.
 * </details>
 * ```
 * @example -docs
 * <details class="pfx-toggle-details -variant-filled">
 *   <summary>Keyboard support</summary>
 *   The native disclosure control supports keyboard interaction.
 * </details>
 * @structure
 * .pfx-toggle-details {
 *   summary {}
 * }
 * @related toggle-group — The bordered, grouped form of the same disclosure.
 */
@scope (.pfx-toggle-details) {
  & {
    color: var(--instui-component-toggle-details-text-color);
    font-family: var(--instui-component-toggle-details-font-family);
    font-weight: var(--instui-component-toggle-details-font-weight);
    line-height: var(--instui-component-toggle-details-line-height);
  }

  & > summary {
    display: flex;
    align-items: center;
    gap: var(--instui-component-toggle-details-icon-margin);
    cursor: pointer;
    list-style: none;
    font-size: var(--instui-component-toggle-details-font-size-medium);
    padding: var(--instui-component-toggle-details-toggle-padding);
    color: var(--instui-component-toggle-details-text-color);
  }

  /* Kill the native disclosure marker; we supply a rotating chevron. */
  & > summary::-webkit-details-marker {
    display: none;
  }

  & > summary::before {
    content: "";
    flex: none;
    inline-size: 1em;
    block-size: 1em;
    background: currentColor;
    -webkit-mask: var(--instui-icon-chevron-right) center / contain no-repeat;
    mask: var(--instui-icon-chevron-right) center / contain no-repeat;
    transition: transform 0.2s ease;
  }

  &[open] > summary::before {
    transform: rotate(90deg);
  }

  /* iconPosition="end" (named -chevron-end, NOT -icon-position-end — a "-icon-" class would collide with the
    shared glyph painter): push the disclosure chevron to the inline-end. */
  &.-chevron-end > summary::before {
    order: 1;
    margin-inline-start: auto;
  }

  /* variant="filled": the summary reads as an action-secondary button. */
  &.-variant-filled > summary {
    background: var(--instui-color-background-interactive-action-secondary-base);
    border-radius: var(--instui-component-toggle-details-toggle-border-radius);
  }

  & > :not(summary) {
    padding: var(--instui-component-toggle-details-content-padding-medium);
  }

  &.-size-sm > summary {
    font-size: var(--instui-component-toggle-details-font-size-small);
  }

  &.-size-sm > :not(summary) {
    padding: var(--instui-component-toggle-details-content-padding-small);
  }

  &.-size-lg > summary {
    font-size: var(--instui-component-toggle-details-font-size-large);
  }

  &.-size-lg > :not(summary) {
    padding: var(--instui-component-toggle-details-content-padding-large);
  }
}

