import { spinnerCss } from "@pantoken/components";
import type { ElementDefinition } from "../lib/context.ts";

/**
 * `<instui-spinner>` — a loading spinner with `role="status"`. `variant="ai"` and
 * `variant="ai-on-color"` select the rotating AI star; size and colour follow the CSS tokens.
 *
 * @example
 * ```html
 * <instui-spinner></instui-spinner>
 * ```
 */
export const spinner: ElementDefinition = {
  name: "spinner",
  define: (ctx) =>
    ctx.wrapper(
      "instui-spinner",
      spinnerCss(ctx.I),
      (host) =>
        `<span class="${ctx.variantClass("spinner", host)}" role="status" part="spinner"></span>`,
    ),
};

/**
 * @component mask
 * @selector .pfx-mask
 * @summary An in-flow overlay that fills its positioned parent and centres its content — e.g. a spinner over a card. For a modal, prefer a native `<dialog>` (its `::backdrop` is the mask). Every one of these modifiers is also available globally (bare, or chained onto any other component) — see the `mask` global utility.
 * @modifier -fullscreen — Fixed to the viewport, covering it at a high z-index.
 * @modifier -blur — Blur what's behind the mask with a backdrop-filter.
 * @example -canvas-rce -docs
 * ```html
 * <div style="position: relative">
 *   <div class="instui-mask">
 *     <span class="instui-spinner"></span>
 *   </div>
 * </div>
 * ```
 * @example -automatica11y
 * ```html
 * <div style="position: relative; min-height: 100px"><div class="pfx-mask"><span class="pfx-spinner" role="status" aria-label="Loading"></span></div></div>
 * ```
 */
/* An in-flow overlay for non-modal cases (e.g. a spinner over a card). For a modal, prefer a native
   <dialog>: its ::backdrop is the mask and reuses the same `--instui-component-mask-background-color`
   token (see modalRules). */
@scope (.pfx-mask) {
  & {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--instui-component-mask-background-color);
  }

  &.-fullscreen {
    position: fixed;
    z-index: 999;
  }

  &.-blur {
    backdrop-filter: blur(0.5rem);
  }
}

