+import assert from "node:assert/strict";
+import { realpathSync } from "node:fs";
+import { createRequire } from "node:module";
+import { basename, resolve, sep } from "node:path";
+
+const repo = "/Users/dwahl/Scripts/pantoken";
+const root = resolve(repo, "a11y-report/2026-10-28T00-36-03.189Z/pages");
+const require = createRequire(realpathSync(resolve(repo, "formats/components/node_modules/automatica11y/package.json")));
+const { chromium } = require("playwright-core");
+const { loadDemoI18n, renderDemoI18n } = await import(resolve(repo, "docs/scripts/demo-i18n.ts"));
+const html = ["spinner", "toggle-details", "mask"].map(name => {
+  const demo = loadDemoI18n(resolve(repo, "docs/demos", name));
+  return renderDemoI18n(demo.template, demo.strings);
+}).join("\n");
+const browser = await chromium.launch({executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", headless: true});
+let cases = 0;
+try {
+  for (const theme of ["rebrand", "canvas", "canvashighcontrast"]) {
+    for (const scheme of ["light", "dark"]) {
+      for (const shadow of [false, true]) {
+        const context = await browser.newContext({javaScriptEnabled: shadow});
+        const page = await context.newPage({viewport: {width: 1280, height: 900}});
+        const errors = [];
+        page.on("pageerror", error => errors.push(error.message));
+        await page.route("http://motion.test/**", async route => {
+          const path = decodeURIComponent(new URL(route.request().url()).pathname);
+          const current = ["/assets/components/components.css", "/assets/components/base.css"].includes(path)
+            ? resolve(repo, "formats/components/dist", basename(path)) : null;
+          const file = current ?? resolve(root, `.${path}`);
+          assert.ok(file === current || file.startsWith(root + sep));
+          await route.fulfill({path: file});
+        });
+        await page.goto(`http://motion.test/spinner-1-${theme}-${scheme}.html`);
+        await page.evaluate((html) => document.querySelector("main").innerHTML = html, shadow
+          ? ["", "inverse", "ai", "ai-on-color"].map(variant => `<instui-spinner${variant ? ` variant="${variant}"` : ""}></instui-spinner>`).join("")
+          : html);
+        if (shadow) await page.addScriptTag({path: resolve(repo, "renderers/web-components/dist/spinner.iife.js")});
+        await page.evaluate(() => document.fonts.ready);
+        const spinners = page.locator(shadow ? "instui-spinner .instui-spinner" : ".instui-spinner");
+        assert.ok(await spinners.count() >= 4);
+        for (const reducedMotion of ["no-preference", "reduce", "no-preference"]) {
+          await page.emulateMedia({reducedMotion});
+          const feedback = await spinners.evaluateAll(nodes => nodes.map(node => {
+            const style = getComputedStyle(node);
+            return {
+              name: style.animationName, display: style.display,
+              width: node.getBoundingClientRect().width, height: node.getBoundingClientRect().height,
+              role: node.getAttribute("role"), label: node.getAttribute("aria-label"),
+              mask: style.maskImage, top: style.borderTopColor, border: style.borderTopWidth,
+              background: style.backgroundImage === "none" ? style.backgroundColor : style.backgroundImage,
+              animations: node.getAnimations().length,
+            };
+          }));
+          for (const item of feedback) {
+            assert.equal(item.name, reducedMotion === "reduce" ? "none" : "pantoken-spinner-rotate");
+            assert.equal(item.role, "status");
+            assert.ok(item.width > 0 && item.height > 0 && item.display !== "none");
+            if (!shadow) assert.ok(item.label);
+            if (reducedMotion === "reduce") assert.equal(item.animations, 0);
+            assert.ok(item.mask !== "none" || Number.parseFloat(item.border) > 0);
+          }
+          if (!shadow) {
+            const disclosure = page.locator("details").nth(1);
+            const summary = disclosure.locator("summary");
+            await summary.focus();
+            const wasOpen = await disclosure.evaluate(node => node.open);
+            await page.keyboard.press("Space");
+            assert.equal(await disclosure.evaluate(node => node.open), !wasOpen);
+            const transition = await summary.evaluate(node => getComputedStyle(node, "::before").transitionDuration);
+            assert.equal(transition, reducedMotion === "reduce" ? "0s" : "0.2s");
+            if (reducedMotion !== "reduce") await new Promise(resolve => setTimeout(resolve, 250));
+            const matrix = await summary.evaluate(node => {
+              const m = new DOMMatrix(getComputedStyle(node, "::before").transform);
+              return {a: m.a, b: m.b, c: m.c, d: m.d};
+            });
+            assert.ok(Math.abs(matrix.a - (wasOpen ? 1 : 0)) < 0.001);
+            assert.ok(Math.abs(matrix.b - (wasOpen ? 0 : 1)) < 0.001);
+            await page.keyboard.press("Enter");
+            assert.equal(await disclosure.evaluate(node => node.open), wasOpen);
+            const mask = page.locator(".instui-mask");
+            const geometry = await mask.evaluate(node => {
+              const a = node.getBoundingClientRect();
+              const b = node.querySelector(".instui-spinner").getBoundingClientRect();
+              return {width: a.width, height: a.height, dx: Math.abs((a.left + a.right - b.left - b.right) / 2), dy: Math.abs((a.top + a.bottom - b.top - b.bottom) / 2)};
+            });
+            assert.ok(geometry.width > 0 && geometry.height > 0);
+            assert.ok(geometry.dx < 1 && geometry.dy < 1);
+          }
+          cases++;
+        }
+        assert.deepEqual(errors, []);
+        await context.close();
+        console.log(`${theme}/${scheme} ${shadow ? "production shadow-DOM spinner" : "JavaScript-disabled localized CSS demos"}: default/reduced/restored motion and visible feedback passed.`);
+      }
+    }
+  }
+  console.log(`${cases} theme/scheme/surface/preference cases passed.`);
+} finally {
+  await browser.close();
+}
