  &.-size-xs {
    height: var(--instui-component-progress-bar-x-small-height);
  }

  &.-size-sm {
    height: var(--instui-component-progress-bar-small-height);
  }

  &.-size-md {
    height: var(--instui-component-progress-bar-medium-height);
  }

  &.-size-lg {
    height: var(--instui-component-progress-bar-large-height);
  }

  & > .bar {
    height: 100%;
    width: clamp(0%, calc((var(--value) - var(--min)) / (var(--max) - var(--min)) * 100%), 100%);
    background: var(--instui-color-background-brand);
    border-radius: var(--instui-component-progress-bar-border-radius);
  }

  & > .value {
    padding: 0 var(--instui-component-progress-bar-value-padding);
    color: var(--instui-component-progress-bar-text-color);
    font-family: var(--instui-component-progress-bar-font-family);
    font-size: var(--instui-component-progress-bar-medium-value-font-size);
    font-weight: var(--instui-component-progress-bar-font-weight);
    line-height: var(--instui-component-progress-bar-line-height);
  }

  &.-color-inverse > .value,
  & > .value.-color-inverse {
    color: var(--instui-component-progress-bar-text-color-inverse);
  }

  /* :indeterminate only matches a valueless <progress>; <meter> always requires a value. */
  &:indeterminate > .bar {
    position: absolute;
    width: 40%;
    animation: pantoken-progress-indeterminate 1.4s ease-in-out infinite;
  }

  &:indeterminate > .value {
    visibility: hidden;
  }

  /* Color modifiers paired with deprecated meter-color aliases via :is(). */
  &:is(.-color-brand, .-meter-color-brand) > .bar {
    background: var(--instui-color-background-brand);
  }

  &:is(.-color-info, .-meter-color-info) > .bar {
    background: var(--instui-color-background-info);
  }

  &:is(.-color-success, .-meter-color-success) > .bar {
    background: var(--instui-color-background-success);
  }

  &:is(.-color-warning, .-meter-color-warning, .-meter-color-alert) > .bar {
    background: var(--instui-color-background-warning);
  }

  &:is(.-color-danger, .-meter-color-danger) > .bar {
    background: var(--instui-color-background-error);
  }

  /* color="primary-inverse": the on-dark scheme. It's a distinct axis from meterColor and overrides it —
     InstUI's inverse meter tokens all collapse to background-base — so it comes AFTER the meter rules and
     wins at equal specificity. Pair it with a dark surface. */
  &.-color-primary-inverse {
    background: var(--instui-component-progress-bar-track-color-inverse);
    border-color: var(--instui-component-progress-bar-border-color-inverse);
    color: var(--instui-component-progress-bar-text-color-inverse);
  }

  &.-color-primary-inverse::after {
    background: var(--instui-component-progress-bar-track-bottom-border-color-inverse);
  }

  &.-color-primary-inverse > .bar {
    background: var(--instui-component-progress-bar-meter-color-brand-inverse);
  }

  &.-render-value-inside > .value {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: flex-start;
  }

  /* Mount/value transition — the interactions layer toggles `-should-animate` on value changes. */
  &.-should-animate > .bar {
    transition: all 0.5s;
  }
}

