     background: var(--instui-color-background-info);
   }

   &:is(.-color-success, .-meter-color-success) > .bar {
     background: var(--instui-color-background-success);
   }

   &:is(.-color-warning, .-meter-color-warning, .-meter-color-alert) > .bar {
     background: var(--instui-color-background-warning);
   }

