/* Slide in from the docked edge on open (native popover + @starting-style, no JS). --tray-slide-x/y
   hold the hidden-state offset per placement; inert where allow-discrete transitions aren't supported. */
@supports (transition-behavior: allow-discrete) {
  &[popover] {
    --tray-slide-x: -100%;
    --tray-slide-y: 0%;
    transition:
      transform 0.2s ease,
      overlay 0.2s allow-discrete,
      display 0.2s allow-discrete;
    transform: translate(0, 0);
  }

  &[popover]:not(:popover-open) {
    transform: translate(var(--tray-slide-x), var(--tray-slide-y));
  }

  @starting-style {
    &[popover]:popover-open {
      transform: translate(var(--tray-slide-x), var(--tray-slide-y));
    }
  }

  /* Inline placements dock to logical start/end, so the slide direction must mirror under an
     ancestor [dir="rtl"]; the end-in-rtl override must win, so it needs one extra class of
     specificity, and the top/bottom resets must come after this generic flip in source order. */
  [dir="rtl"] & {
    --tray-slide-x: 100%;
  }

  &.-placement-end {
    --tray-slide-x: 100%;
  }

