+    mediaBlock("prefers-contrast: more", scope, layer, more),
+    mediaBlock("prefers-contrast: less", scope, layer, less),
+    mediaBlock("prefers-reduced-transparency: reduce", scope, layer, opaque),
+  ]
+    .filter(Boolean)
+    .join("\n\n");
+}
