 import { expect, test } from "vite-plus/test";
 import {
   AGENTS_MD,
   AGENT_TOOLS,
   SCAFFOLD_PLATFORMS,
   installAgentAssets,
   scaffoldAndInit,
   scaffoldProject,
 } from "../src/index.ts";

 test("ships a non-empty AGENTS guide and a known tool set", () => {
   expect(AGENTS_MD).toContain("pantoken");
   expect(AGENT_TOOLS).toContain("cursor");
   expect(AGENT_TOOLS).toContain("claude");
 });

 test("installs a single tool's asset at its conventional path", () => {
   const dir = mkdtempSync(join(tmpdir(), "pantoken-ai-"));
   const written = installAgentAssets("cursor", dir);
   expect(written).toHaveLength(1);
   const rule = join(dir, ".cursor/rules/pantoken.mdc");
   expect(existsSync(rule)).toBe(true);
   expect(readFileSync(rule, "utf8")).toContain("pantoken");
 });

 test("installs all Claude skills + AGENTS.md", () => {
   const dir = mkdtempSync(join(tmpdir(), "pantoken-ai-claude-"));
   installAgentAssets("claude", dir);
   expect(existsSync(join(dir, ".claude/skills/init-pantoken/SKILL.md"))).toBe(true);
   expect(existsSync(join(dir, ".claude/skills/create-pantoken-app/SKILL.md"))).toBe(true);
   expect(existsSync(join(dir, ".claude/skills/create-pantoken-mockup/SKILL.md"))).toBe(true);
   expect(existsSync(join(dir, ".claude/skills/use-pantoken-registry/SKILL.md"))).toBe(true);
   expect(existsSync(join(dir, "AGENTS.md"))).toBe(true);
 });

 test("ships intent routing for apps, browser mockups, and sendable email", () => {
   expect(AGENTS_MD).toContain("Standalone artifact");
   expect(AGENTS_MD).toContain("search @pantoken");
   expect(AGENTS_MD).toContain("@pantoken");
   expect(AGENTS_MD).toContain("@pantoken/email");
   expect(AGENTS_MD).toContain("inlineEmailHtml");
   expect(AGENTS_MD).toContain("pantoken generate email");
 });

 test("installed agent assets link to the published compatibility registry", () => {
   const dir = mkdtempSync(join(tmpdir(), "pantoken-ai-compatibility-"));
   installAgentAssets("all", dir);
   for (const file of [
     "AGENTS.md",
     "llms.txt",
     ".cursor/rules/pantoken.mdc",
     ".github/copilot-instructions.md",
     ".windsurf/rules/pantoken.md",
   ]) {
     expect(readFileSync(join(dir, file), "utf8")).toContain(
       "https://pantoken.app/target-compatibility.json",
     );
   }
   expect(readFileSync(join(dir, "AGENTS.md"), "utf8")).toContain("`$schema`");
 });

 test("installed usage assets describe tree behavior, shadow names, and opt-in validation", () => {
   const dir = mkdtempSync(join(tmpdir(), "pantoken-ai-tree-"));
   try {
     installAgentAssets("all", dir);
     for (const file of [
       "AGENTS.md",
       "llms.txt",
       ".cursor/rules/pantoken.mdc",
       ".github/copilot-instructions.md",
     ]) {
       const content = readFileSync(join(dir, file), "utf8");
       expect(content).toContain("initTreeBrowser");
       expect(content).toContain("aria-owns");
       expect(content).toContain("disclosures");
       expect(content).toContain("tray-label");
       expect(content).toContain("content-label");
       expect(content).toContain("initFormField");
       expect(content).toContain("data-native-validation");
       expect(content).toContain("initMenu");
       expect(content).toContain("data-menu-navigation");
       expect(content).toContain("-layout-responsive");
       expect(content).toContain("instui-container");
       expect(content).toContain("data-label");
       expect(content).toContain("--overflow-x-auto");
     }
   } finally {
     rmSync(dir, { recursive: true, force: true });
   }
 });

 test("'all' writes every asset, deduped", () => {
   const dir = mkdtempSync(join(tmpdir(), "pantoken-ai-all-"));
   const written = installAgentAssets("all", dir);
   expect(existsSync(join(dir, "llms.txt"))).toBe(true);
   expect(existsSync(join(dir, ".github/copilot-instructions.md"))).toBe(true);
