 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8" />
     <title>pantoken scope test</title>

     <!-- The two-sheet multi-scope pair. Registrations once, then the per-theme token blocks
          (scope.lean.css also carries the light/dark color-scheme pins). -->
     <link rel="stylesheet" href="../../generated/properties.lean.css" />
     <link rel="stylesheet" href="../../generated/scope.lean.css" />

     <style>
       body {
         font:
           14px/1.5 ui-monospace,
           monospace;
         margin: 0;
         padding: 24px;
         background: #f6f6f6;
       }
       h1 {
         font-size: 16px;
       }
       h2 {
         font-size: 13px;
         margin: 24px 0 8px;
         text-transform: uppercase;
         letter-spacing: 0.08em;
       }
       .row {
         display: flex;
         gap: 12px;
         flex-wrap: wrap;
         margin-bottom: 8px;
       }

       /* Every probe paints the same two tokens, so any difference between probes comes purely
          from the scope it sits in. */
       .probe {
         background-color: var(--instui-color-background-base);
         color: var(--instui-color-text-base);
         border: 2px solid var(--instui-color-stroke-base);
         border-radius: var(--instui-border-radius-md);
         min-height: var(--instui-size-interactive-height-sm);
         padding: 12px 16px;
         min-width: 200px;
       }
       .probe b {
         display: block;
         font-size: 12px;
         opacity: 0.75;
       }

       #results {
         margin-top: 24px;
         border-top: 1px solid #ccc;
         padding-top: 16px;
       }
       .pass {
         color: #0a7d32;
       }
       .fail {
         color: #b3001b;
         font-weight: bold;
       }
       .note {
         color: #555;
         font-style: italic;
       }
       table {
         border-collapse: collapse;
         font-size: 12px;
       }
       td {
         padding: 2px 10px 2px 0;
         vertical-align: top;
       }
     </style>
   </head>

   <body>
     <h1>pantoken multi-scope check</h1>
     <p class="note">
       Run <code>vp run generate</code> in <code>formats/css</code> first — this page loads the
       sheets from <code>../../generated/</code>, which is gitignored. Open it over
       <code>file://</code>; no server needed.
     </p>
     <p class="note">
       Tests the CSS layer only. Boundaries and instance resolution are runtime concepts in
       <code>@pantoken/scope</code> and are not exercised here.
     </p>

     <h2>1 — sibling scopes: different themes AND different schemes, at once</h2>
     <div class="row">
       <div data-pantoken-theme="rebrand" data-pantoken-scheme="light">
         <div class="probe" id="a"><b>rebrand / light</b>attribute form</div>
       </div>
       <div data-pantoken-theme="rebrand" data-pantoken-scheme="dark">
         <div class="probe" id="b"><b>rebrand / dark</b>attribute form</div>
       </div>

