/**
 * @component progress
 * @selector .pfx-progress
 * @summary A determinate progress bar with a coloured meter, sizes, and an optional value label.
 * @remarks `.value` is a sibling of `.bar`, both children of the root — mirroring how progress-circle nests its own `.value` part. InstUI has no indeterminate state; `:indeterminate` is a pantoken-only best guess (native `<progress>` without a `value` attribute), animating `.bar` as a sliding segment and hiding `.value` since there's no meaningful number to show. `<meter>` has no indeterminate state, so it's unaffected.
 * @element progress, meter
 * @modifier -color-brand — Brand meter colour.
 * @modifier -color-info — Informational meter colour.
 * @modifier -color-success — Success meter colour.
 * @modifier -color-warning — Warning meter colour.
 * @modifier -color-danger — Danger meter colour.
 * @modifier -color-inverse — For dark backgrounds.
 * @modifier -color-primary-inverse — On-dark (primary inverse) meter colour.
 * @modifier -size-xs — Extra small.
 * @modifier -size-sm — Small.
 * @modifier -size-md — Medium (default).
 * @modifier -size-lg — Large.
 * @modifier -should-animate — @interaction Animate meter changes over half a second.
 * @modifier -render-value-inside — Renders `.value` inside the track, aligned to its start, instead of beside it; style it for legibility over the meter colour.
 * @modifier -meter-color-brand — @deprecated {@link -color-brand}
 * @modifier -meter-color-info — @deprecated {@link -color-info}
 * @modifier -meter-color-success — @deprecated {@link -color-success}
 * @modifier -meter-color-warning — @deprecated {@link -color-warning}
 * @modifier -meter-color-alert — @deprecated {@link -color-warning}
 * @modifier -meter-color-danger — @deprecated {@link -color-danger}
 * @part .bar — The filled meter bar.
 * @part .value — The value text beside the bar.
 * @pseudo ::after — Draws the track's bottom rule as its own layer over the meter, so the full border and the bottom border stay independent across themes.
 * @pseudo :indeterminate — Custom, not part of InstUI. Applies only to a native `<progress>` missing its `value` attribute; animates `.bar` as a sliding segment and hides `.value`.
 * @cssproperty --value <number> — The current progress value.
 * @cssproperty --value-now <number> — @alias Alias for `--value`.
 * @cssproperty --min <number> — The minimum meter value (default `0`).
 * @cssproperty --max <number> — The maximum progress value (default `100`).
 * @cssproperty --value-max <number> — @alias {@link --max} The maximum progress value (default `100`).
 * @accessibility Use native `<progress>` for a zero-based task completion range and `<meter>` when the minimum is non-zero. Give either element an accessible name by nesting it in `<label>` or associating a separate `<label>` through matching `for` and `id` values.
 * @compat Scopes the meter part rules with the `@scope` at-rule; browsers without `@scope` support ignore those scoped rules.
 * @example -canvas-rce -docs
 * ### Nested label
 * ```html -canvas-rce -docs
 * <label>
 *   Uploading Document: <progress class="pfx-progress -color-brand" value="70">70%</progress>
 * </label>
 * ```
 * ### External label
 * ```html
 * <label for="storage-used">Storage used</label>
 * <meter id="storage-used" class="pfx-progress -color-warning" min="20" value="40" max="60">50%</meter>
 * ```
 * @structure
 * @variant nested-label {
 *   label {
 *     .pfx-progress {
 *       .bar {}
 *       .value {}
 *     }
 *   }
 * }
 * @variant external-label {
 *   label {}
 *   .pfx-progress {
 *     .bar {}
 *     .value {}
 *   }
 * }
 * @related progress-circle — The circular form of the same determinate progress.
 * @stable
 * @sealed
 * @example -automatica11y
 * ```html
 * <label>
 *   Uploading Document: <progress class="pfx-progress -color-brand" value="70">70%</progress>
 * </label>
 * 
 * <label for="storage-used">Storage used</label>
 * <meter id="storage-used" class="pfx-progress -color-warning" min="20" value="40" max="60">50%</meter>
 * ```
 */
/* Not an InstUI concept: a best guess so a <progress> missing its value attribute (or fed a bad
   --value) reads as loading rather than rendering a broken 0%-width bar. */
@keyframes pantoken-progress-indeterminate {
  0% {
    left: -40%;
  }

  100% {
    left: 100%;
  }
}

