+const { PNG } = require(join(dirname(require.resolve("playwright-core")), "lib/utilsBundle.js"));
+const difference = (first, second) => {
+  const a = PNG.sync.read(first), b = PNG.sync.read(second);
+  let pixels = 0;
+  for (let i = 0; i < a.data.length; i += 4) {
+    if ([0, 1, 2].some(channel => Math.abs(a.data[i + channel] - b.data[i + channel]) > 32)) pixels++;
+  }
+  return pixels;
+};
+const browser = await chromium.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", headless: true });
+try {
+  const page = await browser.newPage({ viewport: { width: 900, height: 1100 } });
+  await page.goto("file:///Users/dwahl/.copilot/session-state/9347a925-530d-4721-9964-9f9d5f3aa58a/files/verify-preferences.html");
+  await page.evaluate(() => {
+    document.body.innerHTML = `
+      <label>Upload<progress id="determinate" class="instui-progress -color-success" value="50" max="100" style="width:300px;height:20px"></progress></label>
+      <label>Score<meter id="meter" class="instui-progress -color-warning" min="20" value="40" max="60" style="width:300px;height:20px"></meter></label>
+      <label>Loading<progress id="loading" class="instui-progress" style="width:300px;height:20px"></progress></label>
+      <label>Circle<progress id="circle" class="instui-progress-circle" value="70" max="100" style="--value:70;width:80px;height:80px"></progress></label>
+    `;
+  });
+  const cdp = await page.context().newCDPSession(page);
+  let cases = 0;
+  for (const theme of ["rebrand", "canvas", "canvasHighContrast"]) {
+    for (const scheme of ["light", "dark"]) {
+      for (const forcedColors of ["none", "active"]) {
+        for (const dir of ["ltr", "rtl"]) {
+          const label = `${theme}/${scheme}/${forcedColors}/${dir}`;
+          await page.evaluate(({ theme, scheme, dir }) => {
+            document.documentElement.dataset.pantokenTheme = theme;
+            document.documentElement.dataset.pantokenScheme = scheme;
+            document.documentElement.dir = dir;
+          }, { theme, scheme, dir });
+          await page.emulateMedia({ colorScheme: scheme, forcedColors, reducedMotion: "reduce" });
+          for (const [id, min, mid, max] of [["determinate", 0, 50, 100], ["meter", 20, 40, 60]]) {
+            const element = page.locator(`#${id}`);
+            await element.evaluate((node, value) => node.value = value, min);
+            const empty = await element.screenshot();
+            await element.evaluate((node, value) => node.value = value, mid);
+            const half = await element.screenshot();
+            await element.evaluate((node, value) => node.value = value, max);
+            const full = await element.screenshot();
+            const halfPixels = difference(empty, half), fullPixels = difference(empty, full);
+            assert.ok(fullPixels > 200, `${label}/${id}: no visible fill`);
+            assert.ok(halfPixels / fullPixels > 0.4 && halfPixels / fullPixels < 0.6,
+              `${label}/${id}: incorrect midpoint geometry ${halfPixels}/${fullPixels}`);
+            await element.evaluate((node, value) => node.value = value, mid);
+            cases++;
+          }
+          const loading = page.locator("#loading");
+          const still = await loading.screenshot();
+          await page.waitForTimeout(210);
+          assert.equal(difference(still, await loading.screenshot()), 0, `${label}: reduced native loading still moves`);
+          for (let repeat = 0; repeat < 2; repeat++) {
+            await page.emulateMedia({ reducedMotion: "no-preference" });
+            const first = await loading.screenshot();
+            await page.waitForTimeout(210);
+            assert.ok(difference(first, await loading.screenshot()) > 10, `${label}: loading never animates/restores`);
+            await page.emulateMedia({ reducedMotion: "reduce" });
+            const stopped = await loading.screenshot();
+            await page.waitForTimeout(120);
+            assert.equal(difference(stopped, await loading.screenshot()), 0, `${label}: live reduction doesn't stop native loading`);
+          }
+          const ring = PNG.sync.read(await page.locator("#circle").screenshot());
+          const sample = (x, y) => [...ring.data.subarray((y * ring.width + x) * 4, (y * ring.width + x) * 4 + 3)];
+          const center = sample(40, 40);
+          for (const x of [25, 30, 35, 45, 50, 55]) {
+            assert.deepEqual(sample(x, 40), center, `${label}: native horizontal paint leaks inside ring`);
+          }
+          const { nodes } = await cdp.send("Accessibility.getFullAXTree");
+          for (const [name, min, value, max] of [["Upload", 0, 50, 100], ["Score", 20, 40, 60]]) {
+            const node = nodes.find(node => !node.ignored && node.name?.value === name);
+            assert.ok(node, `${label}: ${name} inaccessible`);
+            assert.equal(node.value?.value, value);
+            assert.equal(node.properties.find(prop => prop.name === "valuemin")?.value.value, min);
+            assert.equal(node.properties.find(prop => prop.name === "valuemax")?.value.value, max);
+          }
+          cases += 4;
+        }
+      }
+    }
+  }
+  console.log({ nativeProgressCases: cases, liveMotionPixels: "passed", nativeRangeGeometryAndNames: "passed", ringInterior: "passed" });
+} finally {
+  await browser.close();
+}
